sys_script_include.script:
var SLAComplianceManager = Class.create();
SLAComplianceManager.prototype = {
    initialize: function() {
    },
	getBreachedHighPriorityTasks: function(groupId) {

        var breachedTasks = [];

        if (!groupId) {
			return breachedTasks;
        }


        var tasks = new GlideRecord('task');
        tasks.addQuery('sys_class_name', 'IN', 'incident,sc_task'); 
        tasks.addQuery('assignment_group.name', groupId);
        tasks.addQuery('active', true);
        tasks.addQuery('priority', 'IN', '1,2'); 

        tasks.addQuery('due_date', '<', new GlideDateTime()); 
        tasks.query();

        while (tasks.next()) {

            var dueGdt = new GlideDateTime(tasks.getValue('due_date'));
            var nowGdt = new GlideDateTime();

            var duration = GlideDateTime.subtract(dueGdt, nowGdt); 

            var breachedString = duration.getDisplayValue() + " ago"; 

            breachedTasks.push({
                number: tasks.getValue('number'),
                short_description: tasks.getValue('short_description'),
                breached_by: breachedString
            });
        }

        return breachedTasks;
    },
    type: 'SLAComplianceManager'
};
